const wh = $('Webhook').first();
const body = wh.json.body || {};
const documentId = String(body.documentId || '').trim();
const hasFile = Boolean(wh.binary?.file0 || wh.binary?.file);
const errors = [];
if (!documentId) errors.push('documentId é obrigatório.');
if (!hasFile) errors.push('file é obrigatório.');
if (errors.length) {
  return [{ json: { ok: false, code: 'VALIDATION_ERROR', message: errors.join(' '), statusCode: 400 } }];
}
const binKey = wh.binary?.file0 ? 'file0' : 'file';
const bin = wh.binary[binKey];
return [{
  json: {
    ok: true,
    documentId,
    requestId: String($('Normalizar request').first().json.requestId || ''),
    binaryPropertyName: binKey,
    originalFileName: String(bin?.fileName || ''),
    browserMimeType: String(bin?.mimeType || ''),
  },
  binary: wh.binary,
}];

const item = $input.first();
const v = item.json || {};
const duplicateSame = v.duplicateSameDocument === true;
const proceed = v.ok === true && !duplicateSame;
const statusCode = duplicateSame ? 409 : Number(v.statusCode || (proceed ? 200 : 400));
const code = duplicateSame ? 'DUPLICATE_FILE' : (v.code || (proceed ? null : 'FILE_UNREADABLE'));
const message = duplicateSame
  ? (v.message || 'Arquivo duplicado já existe neste documento.')
  : (v.message || (proceed ? null : 'Validação de arquivo falhou.'));
return [{
  json: {
    ...v,
    proceed,
    ok: proceed,
    statusCode,
    code: proceed ? null : code,
    message: proceed ? null : message,
  },
  binary: item.binary,
}];
